	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		CoverageDefinition
	 */
		public CoverageDefinition createCoverageDefinition( CreateCoverageDefinitionCommand command ) {

		CoverageDefinition entity = new CoverageDefinition();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCoverageDefinitionId( command.getCoverageDefinitionId() );
            entity.setName( command.getName() );
            entity.setDefaultLimit( command.getDefaultLimit() );
            entity.setDefaultDeductible( command.getDefaultDeductible() );
            entity.setAsMandatory( command.getAsMandatory() );
            entity.setCoverageType( command.getCoverageType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of CoverageDefinition {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCoverageDefinitionCommand
	 * @return		CoverageDefinition
	 */
	public CoverageDefinition updateCoverageDefinition( UpdateCoverageDefinitionCommand command ) {

		CoverageDefinition entity = new CoverageDefinition();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCoverageDefinitionId( command.getCoverageDefinitionId() );
            entity.setName( command.getName() );
            entity.setDefaultLimit( command.getDefaultLimit() );
            entity.setDefaultDeductible( command.getDefaultDeductible() );
            entity.setAsMandatory( command.getAsMandatory() );
            entity.setProduct( command.getProduct() );
            entity.setCoverageType( command.getCoverageType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of CoverageDefinition {0} ", entity.toString() );

		return entity;
	}

