	public CoverageDefinition getCoverageDefinition( CoverageDefinitionFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CoverageDefinitionFetchOneSummary arg cannot be null" );

		CoverageDefinition entity = null;
		UUID id = summary.getCoverageDefinitionId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a CoverageDefinition using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


